import { Logger } from '@nestjs/common';
import { ResolveField, } from './resolve-field.decorator.js';
const logger = new Logger('GraphQLModule');
/**
 * Property resolver (method) Decorator.
 *
 * @publicApi
 */
export function ResolveProperty(propertyNameOrFunc, typeFuncOrOptions, options) {
    logger.warn('The "@ResolveProperty()" decorator has been deprecated. Please, use the "@ResolveField()" decorator instead.');
    return ResolveField(propertyNameOrFunc, typeFuncOrOptions, options);
}
